<?php
require_once "config/app.php";wajib_login();$page_title="Riwayat voting";$uid=$_SESSION['user']['id'];$s=$conn->prepare("SELECT p.*,k.nama,k.kategori,k.nomor_peserta FROM pembayaran p JOIN kontestan k ON k.id=p.kontestan_id WHERE p.user_id=? ORDER BY p.id DESC");$s->bind_param("i",$uid);$s->execute();$data=$s->get_result();include "includes/header.php";?>
<div class="page-head"><div class="container"><div class="eyebrow">Akun pemilih</div><h1 class="section-title">Riwayat voting</h1><p class="small-muted">Pantau pembayaran dan status suara yang kamu kirim.</p></div></div><div class="container py-5"><div class="panel p-3 p-md-4"><div class="table-responsive"><table class="table"><thead><tr><th>Kontestan</th><th>Jumlah suara</th><th>Total</th><th>Status</th><th>Tanggal</th></tr></thead><tbody><?php if($data->num_rows):while($r=$data->fetch_assoc()):?><tr><td><strong><?=e($r['nama'])?></strong><div class="small-muted"><?=e($r['kategori'])?> • <?=e($r['nomor_peserta'])?></div></td><td><?=$r['jumlah_suara']?></td><td>Rp <?=number_format($r['total_bayar'],0,',','.')?></td><td><span class="badge text-bg-<?=$r['status']==='Disetujui'?'success':($r['status']==='Ditolak'?'danger':'warning')?>"><?=e($r['status'])?></span><?php if($r['catatan_admin']):?><div class="small-muted"><?=e($r['catatan_admin'])?></div><?php endif;?></td><td class="small-muted"><?=e($r['created_at'])?></td></tr><?php endwhile;else:?><tr><td colspan="5" class="text-center small-muted py-4">Belum ada riwayat pembayaran.</td></tr><?php endif;?></tbody></table></div></div></div>
<?php include "includes/footer.php"; ?>